SELECT id
FROM ai_business_application
WHERE tenant_id = #{tenantId}
  AND id = #{applicationId}
  AND del_flag = '0'
FOR UPDATE

SELECT 
FROM ai_business_application_publish_run
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND idempotency_key = #{idempotencyKey}
  AND del_flag = '0'
LIMIT 1

SELECT 
FROM ai_business_application_publish_run
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND id = #{runId}
  AND del_flag = '0'
LIMIT 1

SELECT 
FROM ai_business_application_publish_run
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND del_flag = '0'
ORDER BY create_time DESC, id DESC
LIMIT #{limit}

SELECT COALESCE(MAX(target_version_no), 0)
FROM ai_business_application_publish_run
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND del_flag = '0'

mapper.update:
UPDATE ai_business_application_publish_run
SET run_status = 'RUNNING',
    started_by = #{startedBy},
    update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND id = #{runId}
  AND del_flag = '0'
  AND run_status = 'CREATED'
